SELECT 24, 'If 9x - 3y = 12 and 3x - 5y = 7, what is the exact value of 6x - 2y?', NULL, NULL, '4', '8', '12', '-5', 'B', 'From the first equation: 9x - 3y = 12. Factoring out 3 gives 3(3x - y) = 12, so 3x - y = 4. The requested expression is 6x - 2y = 2(3x - y). Substituting gives 2 * 4 = 8.', 'easy', 45, 1, 'pattern_modeled', 'Mphasis', 'Mphasis Practice Pattern', 0, 'practice_style', NULL
WHERE NOT EXISTS (SELECT 1 FROM `questions` WHERE `question_text` = 'If 9x - 3y = 12 and 3x - 5y = 7, what is the exact value of 6x - 2y?' AND `company_name` = 'Mphasis');

