SELECT 1, 'Two hours after a freight train leaves Delhi, a passenger train leaves the same station traveling in the same direction at an average speed of 60 km/h. If the passenger train overtakes the freight train after 4 hours, what was the average speed of the freight train?', NULL, NULL, '30 km/h', '40 km/h', '45 km/h', '50 km/h', 'B', 'The passenger train travels for 4 hours at 60 km/h, covering 4 * 60 = 240 km. The freight train started 2 hours earlier, so it has traveled for 4 + 2 = 6 hours. Speed of freight train = 240 / 6 = 40 km/h.', 'medium', 60, 1, 'pattern_modeled', 'Mphasis', 'Mphasis Practice Pattern', 0, 'practice_style', NULL
WHERE NOT EXISTS (SELECT 1 FROM `questions` WHERE `question_text` = 'Two hours after a freight train leaves Delhi, a passenger train leaves the same station traveling in the same direction at an average speed of 60 km/h. If the passenger train overtakes the freight train after 4 hours, what was the average speed of the freight train?' AND `company_name` = 'Mphasis');

