SELECT 12, 'A contractor is hired to paint 3 houses. Mr. Brown can paint a house in 6 days, Mr. Black in 8 days, and Mr. Blue in 12 days. If Mr. Brown works for 8 days and Mr. Black works for 6 days, how many days will it take Mr. Blue working alone to complete the remaining contract?', NULL, NULL, '7 days', '9 days', '11 days', '12 days', 'C', 'Total work = 3 houses. Brown in 8 days completes 8 * (1/6) = 4/3 houses. Black in 6 days completes 6 * (1/8) = 3/4 houses. Total work done = 4/3 + 3/4 = 25/12 houses. Remaining work = 3 - 25/12 = 11/12 houses. Blue paints 1/12 house per day. Days for Blue = (11/12) / (1/12) = 11 days.', 'hard', 90, 1, 'pattern_modeled', 'Mphasis', 'Mphasis Practice Pattern', 0, 'practice_style', NULL
WHERE NOT EXISTS (SELECT 1 FROM `questions` WHERE `question_text` = 'A contractor is hired to paint 3 houses. Mr. Brown can paint a house in 6 days, Mr. Black in 8 days, and Mr. Blue in 12 days. If Mr. Brown works for 8 days and Mr. Black works for 6 days, how many days will it take Mr. Blue working alone to complete the remaining contract?' AND `company_name` = 'Mphasis');

