SELECT 2, 'By selling 12 pens for ₹10, a vendor loses 20%. How many pens should he sell for ₹10 in order to gain 20% on the transaction?', NULL, NULL, '6 pens', '8 pens', '9 pens', '10 pens', 'B', 'Selling price of 12 pens = ₹10 at 80% CP. CP of 12 pens = 10 / 0.8 = ₹12.50. CP of 1 pen = 12.50 / 12 = ₹25/24. Target SP with 20% gain = (25/24) * 1.20 = ₹1.25 per pen. Number of pens for ₹10 = 10 / 1.25 = 8 pens.', 'hard', 75, 1, 'pattern_modeled', 'Mphasis', 'Mphasis Practice Pattern', 0, 'practice_style', NULL
WHERE NOT EXISTS (SELECT 1 FROM `questions` WHERE `question_text` = 'By selling 12 pens for ₹10, a vendor loses 20%. How many pens should he sell for ₹10 in order to gain 20% on the transaction?' AND `company_name` = 'Mphasis');

