SELECT 14, 'What will be the final printed value of \'c\' after execution of this pseudo code?', 'Integer a, b, c\nSet a = 10, b = 20, c = 0\nWhile (a < b)\n    c = c + a\n    a = a + 3\nEnd While\nPrint c', 'c', '58', '45', '60', '52', 'A', 'Trace: 1) a=10 (<20): c = 0 + 10 = 10, a=13. 2) a=13 (<20): c = 10 + 13 = 23, a=16. 3) a=16 (<20): c = 23 + 16 = 39, a=19. 4) a=19 (<20): c = 39 + 19 = 58, a=22. 5) a=22 (not <20), loop terminates. Result c = 58.', 'medium', 60, 1, 'pattern_modeled', 'Mphasis', 'Mphasis Practice Pattern', 0, 'practice_style', NULL
WHERE NOT EXISTS (SELECT 1 FROM `questions` WHERE `question_text` = 'What will be the final printed value of \'c\' after execution of this pseudo code?' AND `company_name` = 'Mphasis');

