SELECT 24, 'A container contains 40 liters of pure milk. From this container, 4 liters of milk are drawn out and replaced with water. This replacement procedure is repeated once more. How many liters of pure milk remain in the container?', NULL, NULL, '32.0 liters', '32.4 liters', '34.2 liters', '30.8 liters', 'B', 'Formula: Remaining pure liquid = Initial * (1 - x/V)^n. Here, Initial = 40, x = 4, V = 40, n = 2. Remaining milk = 40 * (1 - 4/40)^2 = 40 * (0.9)^2 = 40 * 0.81 = 32.4 liters.', 'medium', 60, 1, 'pattern_modeled', 'Persistent', 'Persistent Practice Pattern', 0, 'practice_style', NULL
